            /**
             * VyrizeniDlg.
             *
             * @author  Thazmuka
             * @date    09.11.2017
             *
             * @param   parentContent                        The content.
             * @param   ModOtevreni                    mod otevreni dialogu.
             * @return  .
             */
            function GVyrizeniDlg(parentContent, opt, ModOtevreni) {
                const deferred = $.Deferred();
                const options = {
                    ID: "SSLVyrizeniCj#",
                    Ixp: opt ? opt.Ixp : undefined,
                    ViceIxp: opt ? opt.ViceIxp : false,
                    IXPs: opt ? opt.IXPs : undefined
                };
                const pContent = Gordic.Gin.Globals.Dialogs.ZkontrolujContent(parentContent);
                ModOtevreni = Gordic.Gin.Globals.Dialogs.UpravModOtevrni(pContent, ModOtevreni);
                const windowParams = undefined;
                var cntVyrizeni = parentContent.createServiceContent("Gordic.Ssl.WebClient.GVyrizeniMain");
                cntVyrizeni.call("GetTypPisemnosti", { Ixp: opt.Ixp })
                    .then((Pisemnost) => {
                    if (Pisemnost === 0 /* Ginis.DbModel.GWflctysEnum.dokument */ || Pisemnost === 2 /* Ginis.DbModel.GWflctysEnum.typovy_spis */) { // dokument nebo dokument ve spisu
                        Gordic.Gui.Dialogs._openDialog(pContent, deferred, 'Gordic.Ssl.WebClient.GVyrizeniDokument', ModOtevreni, options, windowParams);
                    }
                    else if (Pisemnost === 1 /* Ginis.DbModel.GWflctysEnum.spis */) { // spis
                        Gordic.Gui.Dialogs._openDialog(pContent, deferred, 'Gordic.Ssl.WebClient.GVyrizeniSpis', ModOtevreni, options, windowParams);
                    }
                    else { // neurčeno
                        parentContent.showFlash("jres:32000075"); //RC 32000075 : Neznámý typ písemnosti.
                        deferred.reject();
                    }
                });
                return deferred.promise();
            }
            Dialogs.GVyrizeniDlg = GVyrizeniDlg;
