            //#region vlozeni seznamu pidu dobalíku
            /**
             * vytvoritBalikAVlozitSeznamIxp
             *
             * @param {any} content
             * @param {Wfl.Interface.SelectedRowInfoDto[]} listSelectedRowInfoDto
             * @param {boolean} [isRezimSpisovna] Příznak, zda se bude dokument vytvářet v režimu spisovny.
             */
            static vytvoritBalikAVlozitSeznamIxp(content, listSelectedRowInfoDto, isRezimSpisovna, spisovyZnakDisabled) {
                const def = $.Deferred();
                const IxpList = [];
                for (let i = 0; i < listSelectedRowInfoDto.length; i++) {
                    let row = listSelectedRowInfoDto[i];
                    if (row?.Ixp?.trim()) {
                        IxpList.push(row.Ixp);
                    }
                }
                Utils.GetSrv(content).call("LzeVlozitSeznamIxpDoBaliku", { IxpList: IxpList })
                    .done(function (retVal) {
                    if (retVal.StavBool) {
                        Utils.zadostOvytvoritBalik(content, def, listSelectedRowInfoDto, isRezimSpisovna, spisovyZnakDisabled);
                    }
                    else {
                        content.dialogs.confirm("jres:32170005", //RC 32170005 : Pokračovat?
                        retVal.ErrorMessage + "\n" + "jres:32170004" //RC 32170004 : Chcete v operaci pokračovat ?
                        )
                            // 20.10.2022 - TFeik
                            // Nahrazení obsolete eventu contentclosed za closed.
                            .on("closed", function (ev, answer) {
                            if (answer) {
                                if (answer === "yes") {
                                    Utils.zadostOvytvoritBalik(content, def, listSelectedRowInfoDto, isRezimSpisovna, spisovyZnakDisabled);
                                }
                                else {
                                    def.reject();
                                }
                            }
                            else {
                                def.reject();
                            }
                        });
                    }
                })
                    .fail(function () {
                    def.reject();
                });
                return def.promise();
            }
            /**
             * zadostOvytvoritBalik
             *
             * @param {any} content
             * @param {any} promise
             * @param {any} listSelectedRowInfoDto
             * @param {boolean} [isRezimSpisovna] Příznak, zda se bude dokument vytvářet v režimu spisovny.
             */
            static zadostOvytvoritBalik(content, promise, listSelectedRowInfoDto, isRezimSpisovna, spisovyZnakDisabled) {
                // 28.04.2023 - TFeik
                // Načtení přednastavení balíku přesunuto až na detail balíku přes ixp dokumentu.
                //Utils.nactiOPredvolbyDoBaliku(listSelectedRowInfoDto[0].Ixp)
                //    .done(function (profilInfo) {
                Utils.vytvorBalik(content, null, 
                //{
                //    SpisovyPlan: profilInfo.SpisPlan,
                //    SpisovyZnak: profilInfo.SpisZnak,
                //    RokSkartace: profilInfo.RokSkartace,
                //    SkartacniZnak: profilInfo.SkartZnak,
                //    SkartacniLhuta: profilInfo.SkartLhuta,
                //},
                true, isRezimSpisovna, spisovyZnakDisabled, listSelectedRowInfoDto[0].Ixp)
                    .done(function (balikRetVal) {
                    // 20.02.2020 - TFeik
                    // Přidána kontrola zda byl balík uložen. Pokud ne (uživatel okno zavřel aniž  y vytvořil balík), pak končím.
                    const ixsZup = balikRetVal?.Balik?.ixs_zup;
                    if (balikRetVal?.IsSaved && ixsZup?.trim()) {
                        Utils.vlozitDoBaliku(content, promise, listSelectedRowInfoDto, ixsZup, true);
                    }
                    else {
                        promise.reject();
                    }
                })
                    .fail(function () {
                    promise.reject();
                });
                //})
                //.fail(function () {
                //    promise.reject();
                //});
            }
            //public static nactiOPredvolbyDoBaliku(ixp: string | undefined | null) {
            //    return Utils.GetSrv(content).call<Wfl.WebClient.SSLProfil>("ProfilDokumentuPlanZnakSkart", { Ixp: ixp });
            //}
            static vytvorBalik(content, skartace, zavritBalikPoUlozeni, 
            /**
             * Příznak, zda se bude dokument vytvářet v režimu spisovny.
             * @type {boolean}
             */
            isRezimSpisovna, spisovyZnakDisabled, 
            /**
             * Identifikátor dokumentu pro přednastavení hodnot při nově vytvářeném balíku.
             * @type {string | null}
             */
            inputDataIxp) {
                // 29.07.2019 - TFeik
                // Přidána možnost po vytvoření (uložení nového) balíku automaticky zavřít detail tak,
                // aby jej uživatel nemusel ručně zavírat pro pokračování ve vkládání do balíku.
                return Gordic.Spi.Dialogs.GDetailBalikuDlg(content, {
                    TypZobrazeniDetailu: 1 /* Gin.Interface.TypZobrazeniEntity.New */,
                    InputData: skartace,
                    CloseAfterSave: zavritBalikPoUlozeni,
                    IsRezimSpisovna: isRezimSpisovna,
                    SpisovyZnakDisabled: spisovyZnakDisabled,
                    InputDataIxp: inputDataIxp
                }, Gordic.Global.Enums.ModOtevreni.navigate);
            }
            static vlozitDoBaliku(content, promise, listSelectedRowInfoDto, IxsZup, noveVytvorenyBalik) {
                //const ixps: string[] = [];
                //for (let i = 0; i < listSelectedRowInfoDto.length; i++) {
                //    let ixp = listSelectedRowInfoDto[i].Ixp;
                //    if (ixp) {
                //        ixps.push(ixp);
                //    }
                //}
                const ixps = listSelectedRowInfoDto
                    .map(i => i?.Ixp /* TypeScript nechápe ošetření přes filter, takže lehký ojeb. */)
                    .filter(i => i?.trim());
                // 29.01.2021 - TFeik
                // Přidání vytváření GroupResultu.
                // 28.02.2020 - TFeik
                // Vkládání do balíku pře
                Gordic.Spi.WebClient.GDetailBalikuHandler.VlozitDokumentySpisyDoBaliku(content, {
                    IxsZup: IxsZup,
                    Ixps: ixps,
                    ContinueWhenNonFatal: true
                })
                    .done((vlozitOutput) => {
                    const groupResult = vlozitOutput.GroupResult;
                    if (noveVytvorenyBalik) {
                        Gordic.Spi.Dialogs.GDetailBalikuDlg(content, {
                            IxsZup: IxsZup
                        }, Gordic.Global.Enums.ModOtevreni.navigate)
                            .always(() => {
                            promise.resolve({ GroupResult: groupResult });
                        });
                    }
                    else {
                        promise.resolve({ GroupResult: groupResult });
                    }
                })
                    .fail(() => {
                    promise.reject();
                });
            }
            static SouboryVNearchFormatu(content, ListSelectedRowsInfo) {
                var promis = $.Deferred();
                Utils.GetSrv(content).call("SouboryVNearchFormatu", { ListSelectedRowsInfo: ListSelectedRowsInfo })
                    .then(function (rv) {
                    if (rv && rv.SouboryNearchivniFormat && rv.SouboryNearchivniFormat.length) {
                        var $div = Gordic.Wfl.Dialogs.SouboryVNearchFormatuDlg(content, { SouboryNearchivniFormat: rv.SouboryNearchivniFormat });
                        if ($div) {
                            $div.done(function (retVal) {
                                promis.resolve({ groupResult: rv.GroupResult });
                            });
                        }
                    }
                    else {
                        promis.resolve({ groupResult: rv.GroupResult });
                    }
                });
                return promis.promise();
            }
