            static GetDataLastUsed(input) {
                var data = input.LastUsed;
                var result = [];
                for (var i = 0; i < data.length; i++) {
                    var iconType = Gordic.Wfl.Globals.ListSupport.TypEntityVypocet(data[i].typ_entity_ico);
                    var icon = iconType != null && iconType.icon != null ? iconType.icon : "fa-fw";
                    var secondaryText = data[i].ixp;
                    if (data[i].akt_znacka) {
                        secondaryText = secondaryText + " , " + data[i].akt_znacka;
                    }
                    result.push(new GObservableObject({
                        name: "kpiLastUsed" + "_" + i,
                        icon: icon,
                        primaryText: htmlEncode(data[i].nazev),
                        secondaryText: htmlEncode(secondaryText),
                        ixp: data[i].ixp, // ixp je mimo template a v ts to neprojde. Mohu pouzit secondaryText, ale to je jeste vetsi zverstvo. Zpracovavam v obsluzne akci na klik
                    }));
                }
                return result;
            }
