            static SortSpzn(aObj, bObj) {
                // pokud budu mit v datech oddelené sloupce Denik, Rok, Poradi, pak to mohu ovlivnit podobnou logikou:
                //nmejdřív MD pak ROK pak pořadové číslo
                // sslsden,  por_cislo, rok,
                var a = aObj.data;
                var b = bObj.data;
                var stejne = 0; //0
                var prvniJeVetsi = 1;
                var druheJeVetsi = -1;
                // něco z toho je nevyplněné
                if (a.akt_znacka === b.akt_znacka) {
                    return stejne;
                }
                if (a == null || a === "" || b == null || b === "") {
                    if (a == null || a === "") {
                        return prvniJeVetsi;
                    }
                    else {
                        return druheJeVetsi;
                    }
                }
                if (a.akt_znacka == null || a.akt_znacka === "" || b.akt_znacka == null || b.akt_znacka === "") {
                    if ((a.akt_znacka == null || a.akt_znacka === "") && (b.akt_znacka == null || b.akt_znacka === "")) {
                        return stejne;
                    }
                    else if (a.akt_znacka == null || a.akt_znacka === "") {
                        return druheJeVetsi; // puvodně opačně
                    }
                    else {
                        return prvniJeVetsi; // puvodně opačně
                    }
                }
                var splitedA = a.akt_znacka.split(/[\s/-]+/);
                var splitedB = b.akt_znacka.split(/[\s/-]+/);
                var arraymove = function (arr, fromIndex, toIndex) {
                    var element = arr[fromIndex];
                    arr.splice(fromIndex, 1);
                    arr.splice(toIndex, 0, element);
                };
                var najdiRokAPrehodSCislem = function (pole) {
                    if (pole.length > 2) {
                        // pokud není první v pořadí, délka textu jsou 4 znaky (rok), je číslo, předchozí v poli je taky číslo, a číslo je v rozmezí 1950 až 2050
                        for (var ix = 0; ix < pole.length; ix++) {
                            if (ix > 1 && pole[ix].length === 4 && !isNaN(Number(pole[ix])) && !isNaN(Number(pole[ix - 1])) && (Number(pole[ix]) > 1950) && (Number(pole[ix]) < 2050)) {
                                arraymove(pole, ix, (ix - 1));
                            }
                        }
                    }
                    return pole;
                };
                // když na prvním místě prázdný string
                if (splitedA[0] == null || splitedA[0] === "") {
                    splitedA.splice(0, 1);
                }
                if (splitedB[0] == null || splitedB[0] === "") {
                    splitedB.splice(0, 1);
                }
                //Spojit dva první texty
                if (splitedA.length > 1 && isNaN(Number(splitedA[0])) && isNaN(Number(splitedA[1]))) {
                    splitedA[0] = splitedA[0] + splitedA[1];
                    splitedA.splice(1, 1);
                }
                if (splitedB.length > 1 && isNaN(Number(splitedB[0])) && isNaN(Number(splitedB[1]))) {
                    splitedB[0] = splitedB[0] + splitedB[1];
                    splitedB.splice(1, 1);
                }
                // přehodí rok v pořadí
                najdiRokAPrehodSCislem(splitedA);
                najdiRokAPrehodSCislem(splitedB);
                // nejdříve porovnám první splitnutej at je to cokoli bud celé nebo se splitnul nazev deniku
                if (splitedA[0] > splitedB[0]) {
                    return prvniJeVetsi;
                }
                else if (splitedA[0] < splitedB[0]) {
                    return druheJeVetsi;
                }
                else {
                    // porovnám jednotlivé
                    for (var i = 1; i < splitedA.length; i++) {
                        // pokud jde o poslední porovnání ve foru
                        var last = false;
                        if (((i + 1) >= splitedB.length) || (i + 1) == splitedA.length) {
                            last = true;
                        }
                        if (last == false
                            && splitedA[i] != null
                            && splitedB[i] != null
                            && splitedA[i] == splitedB[i]) {
                            continue;
                        }
                        // texty
                        var firstNumber = Number(splitedA[i]);
                        var secondNumber = Number(splitedB[i]);
                        if (isNaN(firstNumber) || isNaN(secondNumber)) {
                            if (isNaN(firstNumber) && isNaN(secondNumber)) {
                                return splitedA[i] < splitedB[i] ? prvniJeVetsi : druheJeVetsi;
                            }
                            if (isNaN(firstNumber)) {
                                return prvniJeVetsi;
                            }
                            // tady možná dořešit
                        }
                        // oboje čísla
                        if (firstNumber > secondNumber) {
                            return prvniJeVetsi;
                        }
                        if (firstNumber < secondNumber) {
                            return druheJeVetsi;
                        }
                        if (last) {
                            // pokud nejsou stejný počet splitnutých řetěců
                            if (splitedA.length < splitedB.length)
                                return prvniJeVetsi;
                            if (splitedA.length > splitedB.length)
                                return druheJeVetsi;
                        }
                        // pokud stejné jdu na další prvek
                    }
                    // asi už stejné
                    return stejne;
                }
            }
