            static VysledekOperaceIcoColumn(content, extendObj) {
                /// <summary> ikona gridu pro vysledek hromadne operace </summary>
                if (extendObj)
                    Gordic.Wfl.Globals.ListSupport.RozsirNeboInicializujColumnList(extendObj.columnListObj, "ico_status");
                return {
                    name: "ico_status",
                    caption: "jres:31937270", //RC 31937270 : Výsledek operace
                    width: 30,
                    customClass: "center",
                    //fixedWidth: true,
                    iconTemplate: function (row) {
                        var icon = undefined;
                        if (content.GroupResult != null) {
                            var obj = content.GroupResult.find(function (obj) { return obj.Key === row.ixp; });
                            if (obj != null) {
                                if (obj.IsError === true) {
                                    icon = { icon: Gordic.Gin.Icons.StavEnum.neprovedeno, tooltip: obj.Error };
                                }
                                else {
                                    icon = { icon: Gordic.Gin.Icons.StavEnum.provedeno };
                                }
                            }
                        }
                        return icon;
                    }
                };
            }
