            static RegistrovatSablonuPoslednichPouzitych(content) {
                const customProvaider = new Gordic.Dashboard.CustomProvider("jres:31937332", //RC 31937332 : Posledně použité
                'posledni_pouzite', () => {
                    const retDiv = $("<div></div>");
                    const srv = content.createServiceContent({ className: "Gordic.Ssl.WebClient.GSslUtils", params: {} }); //servisni sluzba/content
                    return srv.call("NactiPosledniNavstiveneDokumenty", {})
                        .then((LastUsed) => {
                        const optLoadGridLastUsed = {
                            AppendToDiv: retDiv,
                            LastUsed: LastUsed,
                            Content: null,
                        };
                        Gordic.Ssl.Utils.LoadLastUsedNew(optLoadGridLastUsed);
                        return retDiv;
                    })
                        .always(() => {
                        srv.close();
                    });
                });
                Gordic.Dashboard.CustomProviders.register(customProvaider);
            }
            /**
             * Přednačte potřebné části pro custom seznamy tak, aby jejich následné spuštění nepotřebovalo call na server.
             * To má za následek rychlejší první custom seznamů.
             *
             * @author  TFeik
             * @date    15.03.2022
             */
            static PreloadCustomViews(isl, 
            /**
             * (default: 'all') Typ písemností, pro které se má přednačíst nastavení pro custom seznamy.
             *
             * @type {Wfl.WebClient.GTypPisemnosti[] | 'all'}
             */
            pisemnosti) {
                const promises = [];
                const preloadAll = pisemnosti == null || pisemnosti === 'all';
                let preloadSpis = preloadAll;
                let preloadDokument = preloadAll;
                let preloadDokumentISpis = preloadAll;
                if (!preloadAll && Array.isArray(pisemnosti)) {
                    preloadSpis = pisemnosti.includes('spis');
                    preloadDokument = pisemnosti.includes('dokument');
                    preloadDokumentISpis = pisemnosti.includes('dokumentISpis');
                }
                if (preloadSpis) {
                    promises.push(Ssl.WebClient.GSpisIsl.Init('all', 'all'));
                    promises.push(Ssl.WebClient.GSpisIsl.GetCustomListParams(isl, {
                        VlastnostiUzivatelskeSloupceIxxs: 'all'
                    }));
                }
                else if (preloadDokument) {
                    promises.push(Ssl.WebClient.GDokumentIsl.Init('all', 'all'));
                    promises.push(Ssl.WebClient.GDokumentIsl.GetCustomListParams(isl, {
                        VlastnostiUzivatelskeSloupceIxxs: 'all'
                    }, preloadSpis));
                }
                else if (preloadDokumentISpis) {
                    promises.push(Ssl.WebClient.GSslspidIsl.Init('all', 'all'));
                    promises.push(Ssl.WebClient.GSslspidIsl.GetCustomListParams(isl, {
                        VlastnostiUzivatelskeSloupceIxxs: 'all'
                    }, preloadSpis));
                }
                return $.when(promises)
                    .then(() => {
                    return;
                });
            }
            /**
             * Otevře customizovatelný seznam dokumetů dle kontextu akce.
             *
             * @author  TFeik
             * @date    09.11.2023
             *
             * @param {JQueryEventObject} event
             * @param {any} actionContext
             * @returns {JQuery.Promise<void>}
             */
            static OpenUniverzalDokumenty(event, actionContext) {
                if (!actionContext) {
                    return $.Deferred().reject().promise();
                }
                const contentInfo = Gordic.Utils.FindContentFromEvent(event);
                const parentContent = contentInfo.content;
                try {
                    return Ssl.Dialogs.GDokumentyDlg({
                        ModOtevreni: contentInfo.modOtevreni,
                        parentContent: parentContent,
                        opt: {
                            isl: parentContent.isl,
                            availableFilterFields: Ssl.CustomListUtils.getAvailableBaseFiltersDocument(),
                            availableGridColumns: Ssl.CustomListUtils.getAvailableColumnsDokumenty(),
                            customSettings: actionContext
                        }
                    });
                }
                catch (exception) {
                    return $.Deferred().reject().promise();
                }
            }
