            /**
             * DashboardProvidersRegister
             *
             * @param {GContent} content
             */
            static DashboardProvidersRegister(content) {
                Gordic.Dashboard.Providers.register(new Gordic.Dashboard.IslProvider());
                Gordic.Dashboard.Providers.register(new Gordic.Dashboard.RssProvider());
                Gordic.Dashboard.Providers.register(new Gordic.Dashboard.ArticleProvider());
                Gordic.Dashboard.Providers.register(new Gordic.Dashboard.BlogProvider()); //zapojení blogů     
                Gordic.Dashboard.Providers.register(new Gordic.Dashboard.RestProvider()); //zapojení externích REST služeb
                Gordic.Dashboard.Providers.register(new Gordic.Dashboard.FileProvider()); //zapojení načítání dat ze souboru typu JSON, který je vložen do složky Data v adresáři aplikace
                Gordic.Dashboard.Providers.register(new Gordic.Dashboard.XrgServiceProvider()); //zapojení načítání dat ze XRG služby uvedené ve web.config spolu s nastavenými přístupovými údaji
                Gordic.Dashboard.Providers.register(new Gordic.Dashboard.DataReportProvider()); //zapojení sestav
                // 01.08.2024 - TFeik
                // Registrace custom providerů pro dashboard.
                Ssl.WebClient.DashboardModulInfoProvider.register({});
                Utils.RegistrovatSablonuPoslednichPouzitych(content);
            }
            /**
             * GenerateRandomCislo
             *
             * @param {number} min
             * @param {number} max
             * @returns {number}
             */
            static GenerateRandomCislo(min, max) {
                return Math.floor(Math.random() * (max - min) + min);
            }
            /**
             * JeOpravneniNaVecnouSkupinu
             *
             * @param {Gordic.Gin.Interface.GVecnaSkupinaDto | undefined | null} item
             * @returns {boolean}
             */
            static JeOpravneniNaVecnouSkupinu(item) {
                // return (item && (item.priz_vazba_fun === 0 || (item.priz_opravneni && item.priz_opravneni > 0)))
                return (item && (item.VskUserPermission === 1))
                    ? true
                    : false;
            }
