                vecnaSkupinaChanged() {
                    // thazmuka (13.7.2020) donačtení skartačního znaku a lhůty, protože díky způsobu fungování modelu (=>) se správně nenačtou
                    this.getValueAsync("ixs_vsk")
                        .then((value) => {
                        if (value != null) {
                            this.setValue("skar_znak", { skar_znak: value.skar_znak }, true);
                            //info: pokud se hodnota po nastavení nezmění, může to být kvůli tomu, že je omezena min. hodnotou políčka
                            this.setValue("skar_lhuta", value.skar_lhuta, true);
                        }
                        return this.findForms(this.FormName).gform("waitForValues");
                    })
                        .then(() => {
                        return this.collectData();
                    })
                        .then((collectData) => {
                        this.dto = collectData;
                        return this.call("VecnaSkupinaChanged");
                    })
                        .then(() => {
                        this.setDataToForm();
                        this.setStatesToForm();
                    })
                        .done(() => {
                        this.setFlashLzeUzavritSpisMetodika2023();
                    });
                }
                setValue(name, value, initial) {
                    var method = initial === true ? "setInitial" : "setValue";
                    return this.findForms(this.FormName).findFields(name).gfield(method, value);
                }
                getValueAsync(name) {
                    return this.findForms(this.FormName).findFields(name).gfield("getValueAsync");
                }
                collectData() {
                    var dto = {};
                    this.findForms(this.FormName).findFields().gfield("model", "collect", dto);
                    return dto;
                }
                runSaveAction() {
                    this.hideFlash("IdFlashSave");
                    if (this.PovolenoVyrizeniCiUzavreni === false) {
                        this.showFlash({
                            content: "jres:32000073", //RC 32000073 : Vyřízení či uzavření není povoleno.
                            state: "warning",
                            id: "IdFlashSave"
                        });
                        return;
                    }
                    this.findForms(this.FormName).gform("waitForValues")
                        .then(() => {
                        return this.collectData();
                    })
                        .then((collectData) => {
                        this.dto = collectData;
                        return this.findForms(this.FormName).gform("isValid");
                    })
                        .then((isValid) => {
                        if (isValid === true) {
                            this.preSave();
                        }
                    });
                }
                createSaveParams() {
                    var action = new GAction({
                        name: "actSave",
                        icon: "gi-save",
                        caption: "jres:26255270", //RC 26255270 : Uložit
                        align: "opposite",
                        run: () => {
                            this.runSaveAction();
                        }
                    });
                    this.actions.add(action);
                    var params = {
                        primary: true,
                        favorite: true,
                        action: action
                    };
                    return params;
                }
                createCancelParams() {
                    var action = new GAction({
                        name: "actCancel",
                        caption: "jres:26255255", //RC 26255255 : Zrušit
                        align: "opposite",
                        icon: "gi-window-close",
                        run: () => {
                            this.tryClose();
                        }
                    });
                    this.actions.add(action);
                    var params = {
                        favorite: true,
                        action: action
                    };
                    return params;
                }
                createMenuBar(params) {
                    this.commandBar(params);
                }
                createCommandBar(_params) {
                    var params = [];
                    params.push(this.createSaveParams());
                    params.push(this.createCancelParams()); // Zrušit
                    params = params.concat(_params);
                    this.commandBar(params);
                }
                //#region *** Metody pro uložení ***
                preSave() {
                    this.hideFlash("IdChangePreSaveFlash");
                    if (this.ssl_vyrkonspzn === 1) {
                        this.call("KontrolaSpisPlanu")
                            .then((res) => {
                            if (res.State === false) {
                                this.validateData(res);
                            }
                            else {
                                this.setTypeOfSave();
                            }
                        });
                    }
                    else {
                        this.setTypeOfSave();
                    }
                }
                /** nastavení typu uložení */
                setTypeOfSave() {
                    // hromadné vyřízení
                    if (this.ViceIxp === true) {
                        this.saveMulti();
                    }
                    // jednotlivé vyřízení
                    else {
                        this.saveSingle();
                    }
                }
                /** jednotlivé uložení */
                saveSingle() {
                    //info: kontrolovat metadat jen při uzavření dokumentu
                    // - při vyřízení dokumentu nemusím brát v potaz
                    if (this.ssl_vyrkonmet === 0) { // nekontrolovat metadata
                        this.dealDocumentOrFile(false);
                    }
                    else {
                        // mají se kontrolovat metadat, ale pouze u uzavření, při vyřízení ne
                        if (this.dto?.uzavrit !== true) {
                            this.dealDocumentOrFile(false);
                            return;
                        }
                        // kontrola metadat - naplnění spitkon tabulky
                        this.call("KontrolaMetadat", { Ixp: this.Ixp })
                            .then((res) => {
                            if (res.StavBool === true) { // bez chyby
                                this.dealDocumentOrFile(true);
                                console.log("Vyřízení/uzavření spisu proběhlo bez problému.");
                            }
                            else {
                                //if (this.ssl_vyrkonmet === 1) {                 // pouze varování
                                //    this.dialogs.warning("jres:32000134", "jres:32000133") //RC 32000133 : Při vyřízení/uzavření byly nalezeny chyby metadat.
                                //        .on('close', () => {
                                //            this.dealDocumentOrFile(true);
                                //        })
                                //}
                                //else {  // ssl_vyrkonmet === 2 - zastavit na dialogu opravy metadat
                                //    this.checkingMetadata();
                                //}
                                this.checkingMetadata();
                            }
                        });
                    }
                }
                /** hromadné uložení */
                saveMulti() {
                    this.call("SaveDataAll")
                        .then((GroupResult) => {
                        if (this.retval != null) {
                            this.retval.groupResult = GroupResult; // pro hromadné vyřízení
                            this.retval.stav = true;
                        }
                        this.tryClose();
                    });
                }
                /**
                 * vyřídit dokument nebo spis
                 *
                 * @param {boolean} IsCheckingMetadataOk je kontrola metadat OK?
                 */
                dealDocumentOrFile(IsCheckingMetadataOk) {
                    this.hideFlash("vyriditSaveFlash");
                    this.call("SaveData", { IsKontrolaMetadatOk: IsCheckingMetadataOk })
                        .then((retval) => {
                        // lze vyřídit a uzavřít
                        if (retval.state) {
                            if (this.retval != null) {
                                this.retval.message = retval.message;
                                this.retval.stav = true;
                            }
                            this.tryClose();
                        }
                        // buď se jedná o chybu nebo nelze uzavřít
                        if (!retval.state) {
                            this.showFlash({
                                content: retval.message,
                                state: "error",
                                id: "vyriditSaveFlash"
                            });
                        }
                    });
                }
                /**
                 * kontrola metadat
                 */
                checkingMetadata() {
                    this.hideFlash("metadataFlash");
                    // pouze na uzavření && je vynucena oprava metadat
                    if (this.dto?.uzavrit === true /* && this.ssl_vyrkonmet === 2*/) {
                        // zavolání dialogu kontroly metadat
                        // thazmuka (24.05.2021) - doplnění typu režimu práce
                        Gordic.Wfl.Dialogs.OpravaMetadatDlg(this, {
                            Ixp: this.Ixp,
                            TypKontrolySpisZnakuProp: 0 /* Wfl.Interface.TypKontrolySpisovyZnak.ne */
                        }) // thazmuka - RezimSPZ: false, protoze uz byl vyplnen v ramci vyrizeni
                            .then((retVal) => {
                            if (this.ssl_vyrkonmet === 1) {
                                this.dealDocumentOrFile(true); // posunout se k vyřízení v jakémkoliv případě
                            }
                            else if (this.ssl_vyrkonmet === 2) {
                                if (retVal && retVal.stav === true) {
                                    this.dealDocumentOrFile(true);
                                }
                                else {
                                    this.showFlash({
                                        content: "jres:32000010", //RC 32000010 : Pro vyřízení je třeba opravit všechny chyby metadat.
                                        state: "error",
                                        id: "metadataFlash"
                                    });
                                }
                            }
                        });
                    }
                }
