                addFilterToSpisZnak() {
                    if (this.dto != null) {
                        // doplnění spis. plánu do spisového znaku
                        this.findForms(this.FormName).findFields("spis_znak").gfield("option", {
                            serverFilters: {
                                spis_pl: this.dto.spis_pl,
                                aktivita: [100]
                            }
                        });
                    }
                }
                setDataToForm() {
                    // update serverFilters on spis znak
                    const SpisZnakElement = this.findFields("spis_znak");
                    if (SpisZnakElement != null && SpisZnakElement.length === 1) {
                        SpisZnakElement.gfield("option", "serverFilters", $.extend(SpisZnakElement.gfield("option", "serverFilters"), { spis_pl: this.dto?.spis_pl }));
                    }
                    this.findForms(this.FormName).findFields().gfield("model", "apply", this.dto, { initialValues: true, verificationNeeded: true });
                }
                setStatesToForm() {
                    for (var index = 0; index < this.fieldsName.length; index++) {
                        /** název políčka */
                        var name = this.fieldsName[index];
                        for (var field in this.dtoEnabled) {
                            if (field === "spis_znak") {
                                // nastavení hodnoty spisového plánu se spisového znaku
                                this.findForms(this.FormName).findFields("spis_pl").gfield("option", { disabled: !this.dtoEnabled[field] });
                            }
                            if (name === field) {
                                // nastavení stavu políčka
                                this.findForms(this.FormName).findFields(name).gfield("option", { disabled: !this.dtoEnabled[field] });
                            }
                        }
                    }
                }
                //#region *** change metody ***
                /**
                 * změna pozastavení - platí pro políčka "Pozastavit", "Rok do", "Důvod pozastavení"
                 */
                changePozastaveni() {
                    this.findForms(this.FormName).gform("waitForValues")
                        .then(() => {
                        return this.collectData();
                    })
                        .then((collectData) => {
                        this.dto = collectData;
                    });
                }
                changeZpusobVyrizeni() {
                    this.findForms(this.FormName).gform("waitForValues")
                        .then(() => {
                        return this.collectData();
                    })
                        .then((collectData) => {
                        this.dto = collectData;
                    });
                }
                changeDatumVyrizeni() {
                    this.findForms(this.FormName).gform("waitForValues")
                        .then(() => {
                        return this.collectData();
                    })
                        .then((collectData) => {
                        this.dto = collectData;
                        return this.call("DatumVyrizeniChanged");
                    })
                        .then((res) => {
                        this.validateData(res);
                    })
                        .done(() => {
                        this.setFlashLzeUzavritSpisMetodika2023();
                    });
                }
                changeEnableActionsSchvalovatel() {
                    this.findForms(this.FormName).gform("waitForValues")
                        .then(() => {
                        return this.collectData();
                    })
                        .then((collectData) => {
                        this.dto = collectData;
                    })
                        .then(() => {
                        var state = this.enableActionsSchvalovatel();
                        if (state === true) {
                            this.setDataToForm();
                            this.setStatesToForm();
                        }
                    });
                }
                /**
                 * enableActionsSchvalovatel
                 *
                 * @returns {boolean} na výstupu pokud příjde true - musím občerstvit nastavení políček (setStatesToForm)
                 */
                enableActionsSchvalovatel() {
                    // THAZMUKA - 02.10.2020 ref T6609
                    if (this.gin_epksvyr == true) {
                        if (this.dto == null || this.dtoEnabled == null)
                            return false;
                        if (this.dto.schvalovatel != this.SessionInfoIxsFun && this.SslsdcjSVyriz == 0) {
                            this.dtoEnabled.uzavrit = false;
                            if (this.dto.uzavrit == true)
                                this.dto.uzavrit = false;
                        }
                        else
                            this.dtoEnabled.uzavrit = true;
                        return true;
                    }
                    return false;
                }
