                loadGrid() {
                    var that = this;
                    this.dataGridDokumenty.updateData(this.hromadnyImportItems, "set"); //"add" | "update" | "extend" | "refresh" | "delete" | "set" | "reset";
                    this.privateNaplnPrilohyPodleVybranehoSouboru();
                }
                //#endregion 
                //#region Region Obsluhy Listu
                addFiles() {
                    var that = this;
                    this.dialogPridaniSouboru()
                        .done(function (data) {
                        var model = that.getModel();
                        that.createList(data, (model.ZpracujDle ? model.ZpracujDle : 0));
                        that.loadGrid();
                    });
                }
                createList(files, importDle) {
                    //this.Clear();
                    for (var i = 0; i < files.length; i++) {
                        var l_IsPriloha = false;
                        var IdentifikatorObj = this.getIdentifikator(files[i].filename, importDle);
                        l_IsPriloha = IdentifikatorObj.isPriloha;
                        var l_Index = -1;
                        var containsObj = this.ContainsId(IdentifikatorObj.identifikator);
                        if (containsObj.nalezeno) {
                            this.addNewPrilohu(containsObj.index, files[i], l_IsPriloha);
                        }
                        else {
                            var newGSslHromadnyImportItemDto = {
                                Identifikator: IdentifikatorObj.identifikator,
                                ImportDle: importDle,
                                Prilohy: []
                            };
                            var newIndex = this.hromadnyImportItems.push(newGSslHromadnyImportItemDto) - 1;
                            this.addNewPrilohu(newIndex, files[i], l_IsPriloha);
                        }
                    }
                }
                getIdentifikator(filename, importDle) {
                    var l_Result = "";
                    var isPriloha = false;
                    if (importDle == 0 /* GSslHromadnyImportDleEnum.vse */) { //pokud se importuje vsechno bez ohledu na identifikator. Kazdy soubor bude jedno podani. Nedochazi ke groupovani el. souboru.
                        l_Result = filename.replace(/\.[^/.]+$/, ""); //Path.GetFileNameWithoutExtension(filename);
                        return { identifikator: l_Result, isPriloha: isPriloha };
                    }
                    var l_FileNameNoExt = filename.replace(/\.[^/.]+$/, ""); //Path.GetFileNameWithoutExtension(filename);
                    l_Result = l_FileNameNoExt;
                    if (isNaN(l_FileNameNoExt.slice(-1))) { //posledni znak je nenumericky jedna se o priznak prilohy
                        isPriloha = true;
                        l_Result = l_FileNameNoExt.substring(0, l_FileNameNoExt.length - 1);
                    }
                    return { identifikator: l_Result, isPriloha: isPriloha };
                }
                ContainsId(id) {
                    var index = -1;
                    for (var i = 0; i < this.hromadnyImportItems.length; i++) {
                        if (this.hromadnyImportItems[i].Identifikator?.trim().toUpperCase() === id.trim().toUpperCase()) {
                            index = i;
                            return { nalezeno: true, index: index };
                        }
                    }
                    //nenalezeno
                    return { nalezeno: false, index: index };
                }
                /// <summary>
                /// Vlozi soubor jako novou prilohu
                /// </summary>
                addNewPrilohu(index, file, isPriloha) {
                    if (!this.checkPrilohuIfExists(index, file)) {
                        this.hromadnyImportItems[index].Prilohy.push({ FileInfo: file, IsPriloha: isPriloha, Guid: file.guid });
                        this.selectElObraz(index);
                    }
                }
                checkPrilohuIfExists(index, file) {
                    var prilohy = this.hromadnyImportItems[index].Prilohy;
                    for (var i = 0; i < prilohy.length; i++) {
                        if ((prilohy[i].FileInfo.fileSize == file.fileSize)
                            && (prilohy[i].FileInfo?.filename == file.filename))
                            return true;
                    }
                    return false;
                }
                selectElObraz(index) {
                    var prilohy = this.hromadnyImportItems[index].Prilohy;
                    if (prilohy == null || prilohy.length == 0)
                        return;
                    //pouze jedna priloha, nastavi se jako obraz
                    if (prilohy.length == 1) {
                        prilohy[0].IsElObraz = true;
                        return;
                    }
                    var hromadnyImportItemsTemp = [];
                    for (var i = 0; i < prilohy.length; i++) { //vyberu potencionalni obrazy
                        prilohy[i].IsElObraz = false;
                        if (!prilohy[i].IsPriloha)
                            hromadnyImportItemsTemp.push(prilohy[i]);
                    }
                    if (hromadnyImportItemsTemp.length == 0) { //nenasel zadny potencionalni obraz vybere se prvni priloha
                        prilohy[0].IsElObraz = true;
                    }
                    else { //u potencionalnich obrazu se vzdy vybere prvni
                        hromadnyImportItemsTemp[0].IsElObraz = true;
                    }
                }
