                    if (pocetDokumentu !== 0 && this.aktualniIndexVDruhemKroku > 0) {
                        this.ulozKork2PredUlozenim();
                        this.vymazPoleKrok2();
                        this.aktualniIndexVDruhemKroku = this.aktualniIndexVDruhemKroku - 1;
                        this.nastavKrok2PodleIndexu();
                    }
