                nastavKrok2PodleIndexu() {
                    var that = this;
                    var form = this.findForms("FromKrok1");
                    var fields = form.findFields();
                    var aktualniValue = this.hromadnyImportItems[this.aktualniIndexVDruhemKroku];
                    fields.gfield("model", "apply", aktualniValue);
                    var objApply = {
                        IxsEsu: aktualniValue.IxsEsu
                    };
                    var fieldKartoteka = this.findFields("ExterniSubjekt");
                    fieldKartoteka.gfield("model", "apply", objApply);
                    this.dataGridSouboryKork1.updateData(aktualniValue.Prilohy ? aktualniValue.Prilohy : [], "set");
                }
                ulozKork2PredUlozenim() {
                    var that = this;
                    var form = this.findForms("FromKrok1");
                    var fields = form.findFields();
                    var collectObj = {};
                    fields.gfield("model", "collect", collectObj);
                    for (var i = 0; i < this.hromadnyImportItems.length; i++) {
                        this.hromadnyImportItems[i].Vec = collectObj.Vec;
                        this.hromadnyImportItems[i].VecPodrobne = collectObj.VecPodrobne;
                        this.hromadnyImportItems[i].PocListu = collectObj.PocListu;
                        this.hromadnyImportItems[i].PocPriloh = collectObj.PocPriloh; // TODO
                        this.hromadnyImportItems[i].TypDokumentu = collectObj.TypDokumentu;
                        this.hromadnyImportItems[i].Pristup = collectObj.Pristup;
                        this.hromadnyImportItems[i].SpisPl = collectObj.SpisPl;
                        this.hromadnyImportItems[i].SpisZn = collectObj.SpisZn;
                        this.hromadnyImportItems[i].DetailSaved = true;
                    }
                    var aktualniValue = this.hromadnyImportItems[this.aktualniIndexVDruhemKroku];
                    aktualniValue.PocPriloh = aktualniValue.Prilohy?.length;
                    var fieldKartoteka = this.findFields("ExterniSubjekt");
                    var fieldKartotekaValue = fieldKartoteka.gfield("getValue");
                    if (fieldKartotekaValue) {
                        aktualniValue.IxsEsu = fieldKartotekaValue.ixs_esu;
                        aktualniValue.EsuTxt = fieldKartotekaValue.esu_txt;
                    }
                    else {
                        aktualniValue.IxsEsu = null;
                        aktualniValue.EsuTxt = null;
                    }
                }
                vymazPoleKrok2() {
                    var that = this;
                    this.findFields().gfield("clear");
                }
