                vytvorMenu() {
                    const that = this;
                    const commandBarPole = [];
                    commandBarPole.push({
                        action: new GAction({
                            name: "actOk",
                            caption: "jres:31937340", //RC 31937340 : Vybrat
                            tooltip: "jres:31937339", //RC 31937339 : Vybrat označený subjekt
                            run: function () {
                                that.okClick();
                            }
                        }),
                        favorite: true,
                        customClass: "g-button--primary"
                    });
                    commandBarPole.push({
                        action: new GAction({
                            name: "actClose",
                            caption: "jres:31937341", //RC 31937341 : Zavřít
                            tooltip: "jres:31937342", //RC 31937342 : Zavřít
                            run: function () {
                                that.tryClose();
                            }
                        }),
                        favorite: true
                    });
                    that.commandBar(that.actions.createBar(commandBarPole));
                }
                vytvoritStromoGrid() {
                    var that = this;
                    // GRID
                    var gridSkupinyKolonky = new Gordic.Data.GridFormat();
                    gridSkupinyKolonky.addStructureColumn({
                        name: "mainIco",
                        caption: "jres:31937337", //RC 31937337 : Skupiny externích subjektůjres:31937335
                        //width: 40,
                        fixedWidth: false,
                        sortable: false,
                        iconTemplate: function (data) {
                            if (data.ImageIndex === 1) {
                                return { icon: "fa-building", tooltip: data.Text, text: data.Text };
                            }
                            else if (data.ImageIndex === 2) {
                                return { icon: "fa-cloud", tooltip: data.Text, text: data.Text };
                            }
                            else if (data.ImageIndex === 3) {
                                return { icon: "fa-user", tooltip: data.Text, text: data.Text };
                            }
                            else {
                                return null;
                            }
                        }
                    }).addIconColumn({
                        name: "secoundIco",
                        caption: "jres:31937336", //RC 31937336 : Skupiny
                        //width: 40,
                        //fixedWidth: false,
                        sortable: true,
                        formatPreset: "full",
                        sortOrder: Gordic.Data.Sorting.Inline.text("TextNameOfGroup"),
                        iconTemplate: function (data) {
                            if (data.ImageIndex === 0) {
                                return { icon: "fa-group", tooltip: data.TextNameOfGroup, text: data.TextNameOfGroup };
                            }
                            else {
                                return null;
                            }
                        }
                    });
                    this.actions.add({
                        name: "actDoubleClickSkupiny",
                        run: function (ev, ctx) {
                            console.log(ctx.cellInfo.data);
                            that.okClick();
                        }
                    });
                    this.gridSkupiny = $("<div>").appendTo(this.element)
                        //.height(900)
                        .gautofit()
                        .ggrid({
                        name: "GridSkupiny",
                        //data: ,
                        renderMode: "auto", // auto, all-at-once, paged-sync, paged-async
                        columnMode: "fit", // fit, full
                        navigationMode: "row", // row, cell
                        defaultAction: this.actions.actDoubleClickSkupiny, //selectAction
                        rowsClass: function (dataRow) {
                            if (dataRow.data.ImageIndex !== 0) {
                                return "bold";
                            }
                            else
                                return " ";
                        },
                        //selection: 
                        cellActivate: function (ev, row) {
                            if (row && row.cellInfo && row.cellInfo.data) { // u single modu vzdy 1 ale pro jistotu testuji
                            }
                        },
                        multi: false,
                        searchEngine: null, //false
                        columns: gridSkupinyKolonky,
                    });
                }
