                /**
                 * createGridFormat
                 *
                 * @author  TFeik
                 * @date    19.10.2021
                 *
                 * @returns {Data.GridFormat<Interface.GSpisDto>}
                 */
                static createGridFormat(input, gridFormat, columns, scopeOptions, groupResultProvider) {
                    if (!gridFormat) {
                        gridFormat = new Gordic.Data.GridFormat();
                    }
                    const addMode = Gordic.Gin.WebClient.GSharedIsl.GetAddMode(columns);
                    Gordic.Wfl.WebClient.GWflspidIsl.addDokumentWflGridFormat({
                        input: input,
                        gridFormat: gridFormat,
                        typPisemnosti: 'spis',
                        columns: columns,
                        scopeOptions: scopeOptions,
                        groupResultProvider: groupResultProvider,
                        addMode: addMode
                    });
                    WebClient.GSslspidIsl.addSslspidGridFormat(gridFormat, 'spis', input, addMode, columns, scopeOptions);
                    GSpisIsl.addSpisGridFormat(gridFormat, addMode, columns, scopeOptions);
                    return gridFormat;
                }
