                static createFilterForm(content, params, typPisemnosti, form, initialValues, fields, scope, datumovyInterval, fieldsOptions) {
                    if (!form) {
                        // 24.11.2021 - TFeik
                        // Doplnění tab labelu filtru.
                        form = new Gordic.Forms.Form({
                            tabLabel: Gordic.Wfl.WebClient.GWflspidIsl.GetTextPisemnosti({
                                typPisemnosti: typPisemnosti,
                                dokument: 'jres:32170217', //RC 32170217 : Dokument
                                spis: 'jres:32170218', //RC 32170218 : Spis
                                dokumentISpis: 'jres:32170219' //RC 32170219 : Dokument / spis
                            })
                        });
                    }
                    const addMode = Gordic.Gin.WebClient.GSharedIsl.GetAddMode(fields);
                    Gordic.Wfl.WebClient.GWflspidIsl.addDokumentWflFilterForm({
                        content: content,
                        form: form,
                        params: params,
                        initialValues: initialValues,
                        fields: fields,
                        scope: scope,
                        typPisemnosti: typPisemnosti,
                        datumovyInterval: datumovyInterval,
                        addMode: addMode,
                        fieldsOptions: fieldsOptions
                    });
                    GSslspidIsl.addSslspidFilterForm({
                        content: content,
                        form: form,
                        initialValues: initialValues,
                        fields: fields,
                        scope: scope,
                        typPisemnosti: typPisemnosti,
                        addMode: addMode,
                        fieldsOptions: fieldsOptions
                    });
                    return form;
                }
