                /**
                 * Vrátí objekt pro mapování oprávnění na akce.
                 *
                 * @author  TFeik
                 * @date    18.05.2023
                 *
                 * @returns {CustomView.ActionPermissionMapper<Interface.GSslspidDto>}
                 */
                static createActionPermissionMapper() {
                    const result = Gordic.Wfl.WebClient.GWflspidIsl.createActionPermissionMapperBase();
                    $.merge(result.items, GSslspidIsl.createActionPermissionMapperItems());
                    return result;
                }
                /**
                 * Vrátí jednotlivé položky objektu pro mapování oprávnění na akce.
                 *
                 * @author  TFeik
                 * @date    18.05.2023
                 *
                 * @returns {CustomView.ActionPermissionMapperItem<TDto>[]}
                 */
                static createActionPermissionMapperItems() {
                    const items = [];
                    $.merge(items, Gordic.Wfl.WebClient.GWflspidIsl.createActionPermissionMapperItems());
                    $.merge(items, [
                        {
                            getPermission: (dto) => dto?.Permissions?.LzeZobrazitOdeslani,
                            actionNames: [
                                Gordic.Wfl.PreActions.Names.OtevriOdeslani
                            ]
                        },
                        {
                            getPermission: (dto) => dto?.Permissions?.LzeSchvalit,
                            actionNames: [
                                Gordic.Wfl.PreActions.Names.SchvalitHromadne
                            ]
                        }
                    ]);
                    return items;
                }
