                            inputData: (action, event, ctx, param) => {
                                return input.then((inputRetVal) => {
                                    const { content, get$Grid, getSelectedRows, getActiveRow } = inputRetVal;
                                    const deferred = $.Deferred();
                                    if (!content || content.closed) {
                                        return deferred.reject().promise();
                                    }
                                    const flashMessageId = 'OtevreniDetailuDokumentu';
                                    content.hideFlash(flashMessageId);
                                    const ixp = getActiveRow()?.ixp?.trim();
                                    if (!ixp) {
                                        content.showFlash('jres:31937331', 'error', flashMessageId); //RC 31937331 : Nebyl vybrán žádný řádek.
                                        return deferred.reject().promise();
                                    }
                                    return deferred.resolve({
                                        ModOtevreni: Gordic.Global.Enums.ModOtevreni.navigate,
                                        parentContent: content,
                                        opt: {
                                            grid: get$Grid(),
                                            DetailDto: {
                                                ixp: ixp
                                            }
                                        }
                                    }).promise();
                                });
                            },
                            // 07.03.2022 - TFeik
