                            tema: 'ssl_ptm_predpro',
                            reportStarting: (reportInfo) => {
                                return input.then((inputRetVal) => {
                                    const { content, get$Grid, getSelectedRows, get$Filterpanel } = inputRetVal;
                                    var ixsFunPredavajici = "";
                                    var ixsFunPrebirajici = "";
                                    if (content?.uid?.indexOf("RedistribuceCV") != -1) {
                                        let filters = get$Filterpanel()?.gfilterpanel("getConfirmedData");
                                        ixsFunPredavajici = (filters?.RedistribucePredavajiciVlastnictvi && filters.RedistribucePredavajiciVlastnictvi.Ixs && filters.RedistribucePredavajiciVlastnictvi.Ixs.length > 0) ? filters.RedistribucePredavajiciVlastnictvi.Ixs : "";
                                        ixsFunPrebirajici = (filters?.IxsFunPrebirajici && filters.IxsFunPrebirajici.length > 0) ? filters.IxsFunPrebirajici : "";
                                    }
                                    return Gordic.Wfl.GWflListUtils.CreatePredavaciProtokolPrintParams({
                                        parentContent: content
                                    })
                                        .then((printParams) => {
                                        if (printParams?.LogPorCislo == null
                                            || printParams.IxsFunPredavajici == null
                                            || printParams.IxsFunPrebirajici == null) {
                                            return $.Deferred().reject().promise();
                                        }
                                        reportInfo.params.X0000 = printParams.LogPorCislo.toString();
                                        if (ixsFunPredavajici != "" && ixsFunPrebirajici != "") {
                                            reportInfo.params.X0001 = ixsFunPredavajici;
                                            reportInfo.params.X0002 = ixsFunPrebirajici;
                                        }
                                        else {
                                            reportInfo.params.X0001 = printParams.IxsFunPredavajici;
                                            reportInfo.params.X0002 = printParams.IxsFunPrebirajici;
                                        }
                                        return $.Deferred().resolve().promise();
                                    });
                                });
                            }
