                    /**
                    * GetIslView
                    * @type {function () {}
                    */
                    GetIslView() {
                        var that = this;
                        ////// sandbox seznam spisu vecne skupiny
                        ////var d = Gordic.Isl.Spis.list(
                        ////    rq => {
                        ////        var filters: Ssl.Interface.GSpisFilterDto = {};
                        ////        filters.ixs_vsk = "DEMO02B0A01F";
                        ////        rq.filters = filters;
                        ////        return rq;
                        ////    });
                        this.islView = new Gordic.Isl.View(Gordic.Isl.Dokument.list(rq => {
                            const filtersOrig = rq.filters;
                            if (filtersOrig) {
                                var filtersNew = {};
                                var addFilterSOdes = false;
                                var model = that.model;
                                //   filtersNew.ixp = Gordic.Data.Filtering.parseBaseFilter(Gordic.Data.Filtering.OperatorEnum.Equal, "DEMOX000ALUH"); // docasne
                                if (model.SubTask === 1 /* Wfl.Interface.Lists.DokumentySubTask.Nevyrizene */) {
                                    filtersNew.stav_pis = [10 /* Ginis.DbModel.GWflcstpEnum.nevyrizen */];
                                    filtersNew.stav_dist = [0 /* Ginis.DbModel.GWflcstaEnum.neni_v_distribuci */];
                                }
                                else if (model.SubTask === 2 /* Wfl.Interface.Lists.DokumentySubTask.Vyrizene */) {
                                    filtersNew.stav_pis = [20 /* Ginis.DbModel.GWflcstpEnum.vyrizen */, 30 /* Ginis.DbModel.GWflcstpEnum.uzavren */];
                                    addFilterSOdes = true;
                                }
                                if (filtersOrig.SelectedSubject) {
                                    let ixs = filtersOrig.SelectedSubject.Ixs;
                                    let typeIxs = filtersOrig.SelectedSubject.TypeIxs;
                                    if (ixs && ixs != "") {
                                        if (typeIxs == 0 /* Gin.Interface.IxsType.IxsFun */) {
                                            filtersNew.ixs_fun_akt = [ixs];
                                        }
                                        else {
                                            filtersNew.ixs_su_akt = [ixs];
                                        }
                                    }
                                }
                                if (filtersOrig.DateInterval) {
                                    let from = filtersOrig.DateInterval.date?.start;
                                    let to = filtersOrig.DateInterval.date?.end;
                                    if (filtersOrig.DatumAplikovatNa == "DP") {
                                        filtersNew.dat_pod = filtersOrig.DateInterval.date;
                                    }
                                    else if (filtersOrig.DatumAplikovatNa == "DV") {
                                        filtersNew.dat_vyriz = filtersOrig.DateInterval.date;
                                    }
                                    else {
                                        filtersNew.dat_zmena = filtersOrig.DateInterval.date;
                                    }
                                }
                                //if (filtersOrig.DateInterval) { // místo dat_pod 
                                //    (filtersNew.DatumovyIntervalFactor as any) = filtersOrig.DatumAplikovatNa;
                                //    (filtersNew.DatumovyIntervalValue as any) = filtersOrig.DateInterval.date;
                                //}
                                if (filtersOrig.FiltrSpZn && filtersOrig.FiltrSpZn != "") {
                                    filtersNew.akt_znacka = Gordic.Data.Filtering.parseBaseFilter(Gordic.Data.Filtering.OperatorEnum.Like, filtersOrig.FiltrSpZn);
                                }
                                let vlastni = filtersOrig.TypFiltruPuvod?.includes(0);
                                let cizi = filtersOrig.TypFiltruPuvod?.includes(1);
                                let agendovy = filtersOrig.TypFiltruPuvod?.includes(2);
                                if ((vlastni || cizi) && !(vlastni && cizi)) {
                                    let sPrijValue = vlastni == true ? 0 /* Ginis.DbModel.GWflcsprEnum.interni */ : 1 /* Ginis.DbModel.GWflcsprEnum.doruceny */;
                                    filtersNew.s_prij = [sPrijValue];
                                }
                                // if(agendovy) {
                                // zaškrtávátko Agendový je úplně zbytečný - stará AL tam filtry dává natvrdo pouze v závislosti na db param a nikoli uživatelském zaškrtnutí
                                filtersNew = this.GetTypAgForInFilter(filtersNew);
                                //  }
                                if (filtersOrig.ZobrazitDokumentyFilter) {
                                    filtersNew = this.AddDokumentyFilters(filtersOrig.ZobrazitDokumentyFilter, addFilterSOdes, filtersNew);
                                }
                                if (filtersOrig.ZobrazitNeaktivniFilter) {
                                    let neaktivniFilter = filtersOrig.ZobrazitNeaktivniFilter;
                                    if (neaktivniFilter == 1 /* Wfl.Interface.Lists.SeznamNeaktivnich.STORNOVANE */) {
                                        filtersNew.stav_pis = [60 /* Ginis.DbModel.GWflcstpEnum.stornovan */];
                                    }
                                    else if (neaktivniFilter == 2 /* Wfl.Interface.Lists.SeznamNeaktivnich.ZTRACENE */) {
                                        filtersNew.stav_pis = [70 /* Ginis.DbModel.GWflcstpEnum.ztracen */];
                                    }
                                    else if (neaktivniFilter == 3 /* Wfl.Interface.Lists.SeznamNeaktivnich.PRERUSENE */) {
                                        filtersNew.stav_pis = [80 /* Ginis.DbModel.GWflcstpEnum.zastaven */];
                                    }
                                    else if (neaktivniFilter == 4 /* Wfl.Interface.Lists.SeznamNeaktivnich.ODESLANE */) {
                                        filtersNew.s_odes = 1;
                                    }
                                    else if (neaktivniFilter == 9 /* Wfl.Interface.Lists.SeznamNeaktivnich.PREEVIDOVANE */) {
                                        filtersNew.stav_pis = [200 /* Ginis.DbModel.GWflcstpEnum.preevidovano_do_samostatne_evidence */];
                                    }
                                }
                                rq.filters = filtersNew;
                            }
                            else {
                                //  that.dialogs.alert("Neočekávaný stav!");
                            }
                            return rq;
                        }), {
                            filterPanel: that.filterForm,
                            key: that.GridKey,
                            startEmpty: that.loadGridImmediately !== true,
                            onResponse: (response) => {
                                this.lastFragments = response?.fragments;
                                that.actions.actDetailWfl?.enabled(response.data.length > 0);
                                that.actions.actTiskListWfl?.enabled(that.printRestrictionALF != "");
                                const responseNew = that.sslListSupport.adjustResponse(response, 'IslView', that);
                                return responseNew;
                            }
                        });
                        return this.islView;
                    }
